const long long int t[8] = { 0, 1, 2, 3, 5, 7, 8, 9 };
const long long int powersOfTen[19] = { 1, 10, 100, 1000, 10000, 100000, 1000000, 10000000, 100000000, 1000000000, 
                                          10000000000, 100000000000, 1000000000000, 10000000000000, 
                                          100000000000000, 1000000000000000, 10000000000000000, 
                                          100000000000000000, 1000000000000000000 };

long long int solve(int n) {
    long long int s = 0;
    int baseIndex = 0; 
    while (n > 0) {
        s += (long long int)t[n & 7] * powersOfTen[baseIndex]; 
        baseIndex++; // Increment base index instead of multiplying
        n >>= 3; 
    }
    return s;
}

int main() {
    for (int n; cin >> n && n;) {
        cout << solve(n) << endl;
    }
}

